INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Netzwerkanteil einer IPv4-Adresse immer fix?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von der Subnetzmaske ab"}, {"text": "Ja", "correct": false, "because": "Variiert mit Maske"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Teil der Adresse nutze ich, um das Netzwerk zu identifizieren?', 3, '[{"text": "Netzwerkanteil", "correct": true, "because": "Definiert das Netz"}, {"text": "Hostanteil", "correct": false, "because": "Identifiziert Geräte"}, {"text": "Gesamte Adresse", "correct": false, "because": "Zu unspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen sind korrekt? a) Der Hostanteil kann null sein. b) Der Netzwerkanteil ist immer größer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von der Maske ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Adressaufbau?', 4, '[{"text": "Netzwerkanteil", "correct": false, "because": "Definiert das Netz"}, {"text": "Hostanteil", "correct": false, "because": "Definiert Geräte"}, {"text": "Betriebssystem", "correct": true, "because": "Irrelevant für Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Hostanteil bei 255.255.255.255 existiert?', 2, '[{"text": "Nein", "correct": true, "because": "Broadcast-Adresse"}, {"text": "Ja", "correct": false, "because": "Keine Hostzuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse hat keinen Hostanteil?', 3, '[{"text": "255.255.255.255", "correct": true, "because": "Broadcast-Adresse"}, {"text": "192.168.1.1", "correct": false, "because": "Hat Hostanteil"}, {"text": "10.0.0.0", "correct": false, "because": "Netzwerkadresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile gehören zur IPv4-Struktur?', 5, '[{"text": "Netzwerkanteil", "correct": true, "because": "Identifiziert Netz"}, {"text": "Hostanteil", "correct": true, "because": "Identifiziert Geräte"}, {"text": "Protokollversion", "correct": false, "because": "Nicht in Adresse"}, {"text": "Portnummer", "correct": false, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Netzwerkanteil ist maskenabhängig. b) Der Hostanteil ist immer 8 Bits. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Adressaufbau?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Trennt Anteile"}, {"text": "Bitstruktur", "correct": false, "because": "Definiert Aufbau"}, {"text": "Bildschirmgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Netzwerkanteil bei /24 immer 24 Bits?', 2, '[{"text": "Ja", "correct": true, "because": "Maske definiert 24 Bits"}, {"text": "Nein", "correct": false, "because": "Standarddefinition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Maske im Aufbau?', 4, '[{"text": "Trennt Netzwerk- und Hostanteil", "correct": true, "because": "Definiert Grenze"}, {"text": "Erhöht die Adresszahl", "correct": false, "because": "Begrenzt Hosts"}, {"text": "Ändert die Adresse", "correct": false, "because": "Nur Interpretation"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Hostanteil bei kleinen Netzen wegfällt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Immer vorhanden, aber klein"}, {"text": "Ja", "correct": false, "because": "Hostanteil bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Aufteilen einer Adresse?', 3, '[{"text": "Subnetzmaske", "correct": true, "because": "Definiert Anteile"}, {"text": "Schnelle Zuweisung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufällige Bits", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Hostanteil kann 0 sein. b) Der Netzwerkanteil ist fix 16 Bits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Maske ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen den Hostanteil?', 5, '[{"text": "Subnetzmaske", "correct": true, "because": "Trennt Anteile"}, {"text": "Adresslänge", "correct": true, "because": "32 Bits gesamt"}, {"text": "Protokolltyp", "correct": false, "because": "Nicht in Adresse"}, {"text": "Bandbreite", "correct": false, "because": "Netzwerkleistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Adressaufbau unwichtig?', 3, '[{"text": "Netzwerkanteil", "correct": false, "because": "Definiert Netz"}, {"text": "Hostanteil", "correct": false, "because": "Definiert Geräte"}, {"text": "Farbe der Bits", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann der Netzwerkanteil 0 Bits haben?', 3, '[{"text": "Nein", "correct": true, "because": "Mindestens 1 Bit nötig"}, {"text": "Ja", "correct": false, "because": "Netzdefinition fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 0.0.0.0 einen Netzwerkanteil hat?', 2, '[{"text": "Nein", "correct": true, "because": "Spezialadresse"}, {"text": "Ja", "correct": false, "because": "Keine Netzzuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse nutze ich für einen einzelnen Host?', 4, '[{"text": "192.168.1.1", "correct": true, "because": "Hostanteil vorhanden"}, {"text": "192.168.1.0", "correct": false, "because": "Netzwerkadresse"}, {"text": "255.255.255.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft hat der Netzwerkanteil?', 3, '[{"text": "Maskenabhängig", "correct": true, "because": "Grenze variiert"}, {"text": "Immer 24 Bits", "correct": false, "because": "Abhängig von /n"}, {"text": "Hostunabhängig", "correct": false, "because": "Teil der Struktur"}]');
